const { useState } = React;

function App() {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [twoFAEnabled, setTwoFAEnabled] = useState(false);

  function handleUpdatePassword(e) {
    e.preventDefault();
    if (!currentPassword || !newPassword || !confirmPassword) {
      setError("All fields are required.");
      return;
    }
    setError("");
    // Here you could add further validation or submit logic
    alert("Password updated successfully (simulated).");
    setCurrentPassword("");
    setNewPassword("");
    setConfirmPassword("");
  }

  return (
    <main style={{
      fontFamily: 'Arial, sans-serif',
      maxWidth: 480,
      margin: '2rem auto',
      padding: '0 1rem',
      color: '#222'
    }}>
      <h1 style={{ fontWeight: 'normal', fontSize: '1.5rem', marginBottom: '1.5rem' }}>Security</h1>

      <section
        aria-labelledby="change-password-title"
        style={{
          border: '1.5px solid #444',
          borderRadius: 8,
          padding: '1rem 1.25rem',
          marginBottom: '2rem'
        }}
      >
        <h2 id="change-password-title" style={{ fontWeight: 'normal', fontSize: '1.1rem', marginBottom: '1rem' }}>
          Change password
        </h2>

        <form onSubmit={handleUpdatePassword} noValidate>
          <label htmlFor="current-password" style={{ display: 'block', marginBottom: 6, fontSize: '0.9rem' }}>
            Current password
          </label>
          <input
            id="current-password"
            type="password"
            value={currentPassword}
            onChange={e => setCurrentPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '0.5rem',
              marginBottom: '1rem',
              fontSize: '1rem',
              borderRadius: 4,
              border: '1.5px solid #999'
            }}
          />

          <label htmlFor="new-password" style={{ display: 'block', marginBottom: 6, fontSize: '0.9rem' }}>
            New password
          </label>
          <input
            id="new-password"
            type="password"
            value={newPassword}
            onChange={e => setNewPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '0.5rem',
              marginBottom: '1rem',
              fontSize: '1rem',
              borderRadius: 4,
              border: '1.5px solid #999'
            }}
          />

          <label htmlFor="confirm-password" style={{ display: 'block', marginBottom: 6, fontSize: '0.9rem' }}>
            Confirm new password
          </label>
          <input
            id="confirm-password"
            type="password"
            value={confirmPassword}
            onChange={e => setConfirmPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '0.5rem',
              marginBottom: '1rem',
              fontSize: '1rem',
              borderRadius: 4,
              border: '1.5px solid #999'
            }}
          />

          {error && (
            <p role="alert" style={{ color: 'red', marginBottom: '1rem', fontSize: '0.9rem' }}>
              {error}
            </p>
          )}

          <button
            type="submit"
            style={{
              padding: '0.5rem 1.25rem',
              fontSize: '1rem',
              borderRadius: 20,
              border: '1.5px solid #444',
              backgroundColor: 'transparent',
              cursor: 'pointer'
            }}
          >
            Update password
          </button>
        </form>
      </section>

      <section
        aria-labelledby="two-fa-title"
        style={{
          border: '1.5px solid #444',
          borderRadius: 8,
          padding: '1rem 1.25rem'
        }}
      >
        <h2 id="two-fa-title" style={{ fontWeight: 'normal', fontSize: '1.1rem', marginBottom: '0.75rem' }}>
          Two-factor authentication
        </h2>

        <label style={{ display: 'flex', alignItems: 'center', fontSize: '0.95rem', cursor: 'pointer' }}>
          <input
            type="checkbox"
            checked={twoFAEnabled}
            onChange={e => setTwoFAEnabled(e.target.checked)}
            style={{ marginRight: 8, width: 16, height: 16, cursor: 'pointer' }}
          />
          Enable 2FA
        </label>
      </section>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

